 private boolean resolveProviderAfterFailure(int generation,int what,int extra){String kind=getIntent().getStringExtra("itemKind");if(resolvedProvider||live||localMedia()||!Arrays.asList("vod","episode").contains(kind)||video.responseStatus()==401||video.responseStatus()==403)return false;resolvedProvider=true;final Intent intent=getIntent();metadataWorker.execute(()->{String candidate="";try{org.json.JSONObject item=metadataItem(intent);candidate=IptvStore.get(this).resolvePlayback(item);}catch(Exception ignored){}final String repaired=candidate;runOnUiThread(()->{if(generation!=sourceGeneration||isFinishing())return;if(!repaired.isEmpty()&&!sources.contains(repaired)){sources.add(repaired);sourceIndex=sources.size()-1;beginSource(false);}else sourceFailed(generation,what,extra);});});return true;}
