 private void externalPlayer(){if(sources==null||sources.isEmpty()){finish();return;}try{String address=currentUrl.isEmpty()?sources.get(0):currentUrl;Intent view=new Intent(Intent.ACTION_VIEW).setDataAndType(Uri.parse(address),"video/*");view.putExtra(Intent.EXTRA_TITLE,getIntent().getStringExtra("name"));if(localMedia()){view.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);view.setClipData(ClipData.newRawUri("Local video",Uri.parse(address)));}ExternalLaunch.open(this,Intent.createChooser(view,t("اختار مشغّل فيديو مثبت على الجهاز","Choose an installed video player")));finish();}catch(RuntimeException e){Toast.makeText(this,t("لم يتم فتح مشغّل آخر. ثبّت مشغّل فيديو متوافق ثم جرّب مجددًا.","No other player opened. Install a compatible video player and try again."),Toast.LENGTH_LONG).show();errorVisible=false;playbackError(1,-1010);}}

 private void loadPoster(ImageView target,String address){if(address==null||!address.matches("https?://.+"))return;new Thread(()->{java.net.HttpURLConnection c=null;try{c=(java.net.HttpURLConnection)new java.net.URL(address).openConnection();c.setConnectTimeout(5000);c.setReadTimeout(5000);try(java.io.InputStream in=c.getInputStream();java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>1048576)return;out.write(b,0,n);}byte[] data=out.toByteArray();BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=4;Bitmap bitmap=BitmapFactory.decodeByteArray(data,0,data.length,options);runOnUiThread(()->{if(!isDestroyed())target.setImageBitmap(bitmap);});}}catch(Exception ignored){}finally{if(c!=null)c.disconnect();}},"player-poster").start();}
 private static String clock(int ms){int s=Math.max(0,ms/1000);return s>=3600?String.format(java.util.Locale.US,"%02d:%02d:%02d",s/3600,s/60%60,s%60):String.format(java.util.Locale.US,"%02d:%02d",s/60,s%60);}
 private boolean panelsOpen(){return (channelBrowser!=null&&channelBrowser.showing())||(rightPanel!=null&&rightPanel.getVisibility()==View.VISIBLE);}
 private boolean focusInDialog(){try{View f=getCurrentFocus();if(f==null||f==video||f==timeline)return false;View p=f.getParent() instanceof View?(View)f.getParent():null;while(p!=null){if(p==controls||cinemaChrome!=null&&p==cinemaChrome.top)return false;if(!(p.getParent() instanceof View))break;p=(View)p.getParent();}return true;}catch(Exception e){return false;}}
 private void rehide(){timer.postDelayed(hide,2000);}
 private final Runnable hide=()->{if(prepared&&video.isPlaying()&&!dragging&&!seekHold.active()&&!panelsOpen()&&!focusInDialog()&&!(cinemaChrome!=null&&cinemaChrome.containsTop(getCurrentFocus()))){hidePlaybackChrome();}else if(panelsOpen()||focusInDialog())rehide();};
