 private void changeLive(int delta){long now=android.os.SystemClock.uptimeMillis();if(now-lastChannelKey<300)return;lastChannelKey=now;IptvActivity.changeLive(delta,getIntent().getStringExtra("itemId"));}
 private boolean revealingControls;
 private LinearLayout actionRow(){return actionRow;}
 private boolean actionFocused(){View focused=getCurrentFocus();LinearLayout row=actionRow();return focused!=null&&row!=null&&focused.getParent()==row;}
 private void focusActions(){LinearLayout row=actionRow();if(row==null)return;for(int i=0;i<row.getChildCount();i++){View child=row.getChildAt(i);if(child.isEnabled()&&child.getVisibility()==View.VISIBLE){child.requestFocus();return;}}}
 private boolean navigatePlaybackControls(KeyEvent e){if(controls==null||controls.getVisibility()!=View.VISIBLE||e.getAction()!=KeyEvent.ACTION_DOWN)return false;int code=e.getKeyCode();if(code!=KeyEvent.KEYCODE_DPAD_UP&&code!=KeyEvent.KEYCODE_DPAD_DOWN)return false;if(code==KeyEvent.KEYCODE_DPAD_DOWN&&getCurrentFocus()==timeline){finishScrub(false,true);focusActions();return true;}if(code==KeyEvent.KEYCODE_DPAD_UP&&actionFocused()){if(timeline!=null&&timeline.isEnabled())timeline.requestFocus();else if(cinemaChrome!=null)cinemaChrome.moveFromTimeline(code);return true;}if(cinemaChrome!=null&&cinemaChrome.containsTop(getCurrentFocus()))return cinemaChrome.moveFromTop(code,timeline,pauseButton);if(code==KeyEvent.KEYCODE_DPAD_UP&&getCurrentFocus()==timeline)return cinemaChrome!=null&&cinemaChrome.moveFromTimeline(code);return false;}
