 private boolean playerBackDown;
 @Override public boolean dispatchKeyEvent(KeyEvent e){if(!phoneMode&&TvSourceKey.handle(this,e))return true;int code=e.getKeyCode();if(code==KeyEvent.KEYCODE_VOLUME_UP||code==KeyEvent.KEYCODE_VOLUME_DOWN){if(e.getAction()==KeyEvent.ACTION_DOWN){android.media.AudioManager audio=(android.media.AudioManager)getSystemService(AUDIO_SERVICE);int current=audio.getStreamVolume(android.media.AudioManager.STREAM_MUSIC);audio.setStreamVolume(android.media.AudioManager.STREAM_MUSIC,Math.max(0,Math.min(audio.getStreamMaxVolume(android.media.AudioManager.STREAM_MUSIC),current+(code==KeyEvent.KEYCODE_VOLUME_UP?1:-1))),android.media.AudioManager.FLAG_SHOW_UI);}return true;}if(phoneMode&&(code==KeyEvent.KEYCODE_MEDIA_PAUSE||code==KeyEvent.KEYCODE_MEDIA_PLAY)){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0){phonePlayRequested=code==KeyEvent.KEYCODE_MEDIA_PLAY;if(adhanPaused){PhoneFaithAudio.cancel(this,phonePlayRequested);return true;}if(prepared){if(phonePlayRequested)video.start();else video.pause();update();}}return true;}if(live&&!kids()&&!errorVisible&&(code==KeyEvent.KEYCODE_CHANNEL_UP||code==KeyEvent.KEYCODE_CHANNEL_DOWN)){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0)changeLive(code==KeyEvent.KEYCODE_CHANNEL_UP?1:-1);return true;}if(code==KeyEvent.KEYCODE_GUIDE&&channelBrowser!=null){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0)channelBrowser.open();return true;}if(code==KeyEvent.KEYCODE_BACK&&channelBrowser!=null&&channelBrowser.showing()&&channelBrowser.contains(getCurrentFocus())&&channelBrowser.inContent()){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0)channelBrowser.backToCategories();return true;}if(code==KeyEvent.KEYCODE_BACK&&panelsOpen()){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0){View origin=channelBrowser!=null&&channelBrowser.showing()?channelBrowser.returnFocus():panelOrigin;if(channelBrowser!=null&&channelBrowser.showing())channelBrowser.dismiss();hideRightPanel();setChromeVisibility(View.VISIBLE);if(origin!=null&&origin.isShown())origin.requestFocus();else gearButton.requestFocus();}return true;}if(channelBrowser!=null&&channelBrowser.showing()&&channelBrowser.contains(getCurrentFocus())&&code==KeyEvent.KEYCODE_DPAD_RIGHT){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0){if(!channelBrowser.focusContent()){channelBrowser.dismiss();show();}}return true;}if(rightPanel!=null&&rightPanel.getVisibility()==View.VISIBLE){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0&&(code==KeyEvent.KEYCODE_DPAD_LEFT||code==KeyEvent.KEYCODE_MENU)){hideRightPanel();if(panelOrigin!=null&&panelOrigin.isShown())panelOrigin.requestFocus();else gearButton.requestFocus();return true;}return super.dispatchKeyEvent(e);}if(code==KeyEvent.KEYCODE_BACK){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0)playerBackDown=true;else if(e.getAction()==KeyEvent.ACTION_UP){boolean leave=playerBackDown&&!e.isCanceled();playerBackDown=false;if(leave)backFromPlayback();}return true;}if(live&&!errorVisible&&channelBrowser!=null&&!channelBrowser.showing()&&(code==KeyEvent.KEYCODE_DPAD_CENTER||code==KeyEvent.KEYCODE_ENTER)&&(controls.getVisibility()!=View.VISIBLE||getCurrentFocus()==null||getCurrentFocus()==pauseButton||getCurrentFocus()==video)){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0){revealingControls=true;setChromeVisibility(View.VISIBLE);channelBrowser.open();}return true;}if(code==KeyEvent.KEYCODE_DPAD_CENTER||code==KeyEvent.KEYCODE_ENTER){if(e.getAction()==KeyEvent.ACTION_DOWN&&controls.getVisibility()!=View.VISIBLE){revealingControls=true;show();return true;}if(revealingControls){if(e.getAction()==KeyEvent.ACTION_UP)revealingControls=false;return true;}}if(!live&&(code==KeyEvent.KEYCODE_MEDIA_FAST_FORWARD||code==KeyEvent.KEYCODE_MEDIA_REWIND)){if(e.getAction()==KeyEvent.ACTION_DOWN)beginScrub(code==KeyEvent.KEYCODE_MEDIA_REWIND?KeyEvent.KEYCODE_DPAD_LEFT:KeyEvent.KEYCODE_DPAD_RIGHT,e.getRepeatCount()>0);else if(e.getAction()==KeyEvent.ACTION_UP)finishScrub(true,true);return true;}if(!kids()&&(code==KeyEvent.KEYCODE_MEDIA_NEXT||code==KeyEvent.KEYCODE_MEDIA_PREVIOUS)){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0){int delta=code==KeyEvent.KEYCODE_MEDIA_NEXT?1:-1;if(live)changeLive(delta);else adjacent(delta);}return true;}if(navigatePlaybackControls(e))return true;if(!errorVisible&&(code==KeyEvent.KEYCODE_DPAD_UP||code==KeyEvent.KEYCODE_DPAD_DOWN)&&controls.getVisibility()!=View.VISIBLE){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0){show();if(code==KeyEvent.KEYCODE_DPAD_UP&&cinemaChrome!=null)cinemaChrome.moveFromTimeline(code);}return true;}return super.dispatchKeyEvent(e);}


 private android.graphics.drawable.GradientDrawable ovalDraw(int color,int strokeColor,int strokeWidth){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setShape(android.graphics.drawable.GradientDrawable.OVAL);d.setColor(color);if(strokeWidth>0)d.setStroke(dp(strokeWidth),strokeColor);return d;}
