 private final Runnable checkpoint=new Runnable(){public void run(){long deadline=getIntent().getLongExtra("parentalDeadline",0);if(deadline>0&&System.currentTimeMillis()>=deadline){video.pause();Toast.makeText(PlayerActivity.this,t("انتهى الوقت المسموح. يلزم رقم الأهل لفتح المحتوى.","Time allowance ended. Parent PIN required to open content."),Toast.LENGTH_LONG).show();finish();return;}long now=SystemClock.uptimeMillis();int picture=videoStartRecovery.observe(now,prepared&&video.isPlaying()&&!adhanPaused,video.videoExpected(),video.hasVideoFrame(),video.getCurrentPosition());if(picture==VideoStartRecovery.QUALITY&&!video.recoverVideoQuality()){videoStartRecovery.skipQuality();picture=VideoStartRecovery.ENGINE;}if(picture==VideoStartRecovery.UNSUPPORTED){playbackError(1,-1010);return;}if(picture==VideoStartRecovery.ENGINE&&engineRecovery.tryAlternate(Integer.MIN_VALUE,localMedia())){if(!live)pendingResume=video.getCurrentPosition();boolean alternate=!video.buffered();if(live&&alternate)video.useLiveBuffered();else video.useBuffered(alternate);beginSource(false);}if(now-lastCheckpoint>=5000){remember();lastCheckpoint=now;}if(controls.getVisibility()==View.VISIBLE||seekHold.active()||dragging)update();timer.postDelayed(this,1000);}};
 private void toggle(){if(adhanPaused){if(phoneMode){phonePlayRequested=true;PhoneFaithAudio.cancel(this,true);}else AdhanPlayback.get(this).cancel();return;}if(!prepared)return;if(video.isPlaying()){phonePlayRequested=false;remember();video.pause();show();}else{phonePlayRequested=true;video.start();scheduleHide();}update();}
 private void beginScrub(int code,boolean repeat){if(!prepared||live)return;long now=SystemClock.uptimeMillis();boolean already=seekHold.active();if(!already&&repeat)return;int base=already?(int)seekHold.position():requestedSeek>=0?requestedSeek:video.getCurrentPosition();if(!already){scrubWasPlaying=video.isPlaying()||resumeAfterSeek;scrubPaused=resumeAfterSeek&&!video.isPlaying();resumeAfterSeek=false;setChromeVisibility(View.VISIBLE);timeline.requestFocus();}if(!seekHold.begin(code,repeat,now,base,video.getDuration()))return;timer.removeCallbacks(hide);timer.removeCallbacks(scrubFrame);update();timer.postDelayed(scrubFrame,16);}
 private final Runnable scrubFrame=new Runnable(){public void run(){if(!seekHold.active()||!prepared||isFinishing())return;long now=SystemClock.uptimeMillis();if(seekHold.stale(now)){finishScrub(true,true);return;}seekHold.advance(now);if(seekHold.held(now)&&!scrubPaused){if(video.isPlaying())video.pause();scrubPaused=true;}update();timer.postDelayed(this,16);}};
 private void finishScrub(boolean commit,boolean resume){if(!seekHold.active())return;int target=(int)seekHold.position();seekHold.reset();timer.removeCallbacks(scrubFrame);if(commit&&prepared&&!live){requestedSeek=target;seekingResume=true;resumeAfterSeek=resume&&scrubPaused&&scrubWasPlaying;video.seekTo(target);}else if(resume&&scrubPaused&&scrubWasPlaying&&active==this)video.start();scrubPaused=false;update();scheduleHide();}
 private void seek(int delta){if(!prepared||live||video.getDuration()<=0)return;finishScrub(false,true);requestedSeek=Math.max(0,Math.min(Math.max(0,video.getDuration()-1000),(requestedSeek>=0?requestedSeek:video.getCurrentPosition())+delta));seekingResume=true;video.seekTo(requestedSeek);setChromeVisibility(View.VISIBLE);update();scheduleHide();}
 private void commitSeek(){if(prepared&&!live&&video.getDuration()>0){requestedSeek=(int)(Math.min(Math.max(0,video.getDuration()-1000),video.getDuration()*(timeline.getProgress()/100000.0)));seekingResume=true;video.seekTo(requestedSeek);update();}}
 private void remember(){if(!live&&!completed&&!failed&&!seekingResume&&!seekHold.active()&&!dragging&&prepared&&UiSettings.prefs(this).getBoolean("resume",true))try{PlaybackMemory.put(this,resumeKey,video.getCurrentPosition(),video.getDuration());}catch(Exception ignored){}}
