 private void playbackStatus(){long now=SystemClock.uptimeMillis();String details=String.valueOf(channelTitle.getText())+"\n"+String.valueOf(contentMeta.getText())+"\n"+String.valueOf(contentPlot.getText())+"\n\n"+t("المشغّل: ","Player: ")+(video.buffered()?"Media3 / ExoPlayer":"Android MediaPlayer")+"\n"+(video.buffered()?t("بافر أمامي: ","Buffered ahead: ")+String.format(java.util.Locale.US,"%.1f",video.bufferedAhead()/1000.0)+" s\n":"")+t("انتظار بيانات البث: ","Waiting for stream data: ")+(diagnostics.active()?t("نعم","Yes"):t("لا","No"))+"\n"+t("عدد الوقفات أثناء التشغيل: ","Rebuffer events during playback: ")+diagnostics.count()+"\n"+t("مدة انتظار البيانات: ","Time waiting for data: ")+String.format(java.util.Locale.US,"%.1f",diagnostics.millis(now)/1000.0)+" s\n"+t("المحمّل من الملف: ","File buffered: ")+video.getBufferPercentage()+"%\n"+t("دقة الفيديو: ","Video resolution: ")+video.width+" × "+video.height+"\n"+t("سرعة التشغيل: ","Playback speed: ")+rateText(playbackRate)+"\n"+video.streamInformation()+"\n\n"+t("هذه مؤشرات من المشغل وليست قياسًا لسرعة الإنترنت. إذا استمر الصوت وتوقفت الصورة فقد يلزم فحص ترميز الفيديو على الجهاز.","These are player signals, not an Internet speed test. If audio continues while video freezes, the device's video decoding needs checking.");presentDetails(t("معلومات البث","Stream Information"),details);}
