 private void enterPictureInPicture(){if(!phoneMode)return;if(Build.VERSION.SDK_INT<26||!getPackageManager().hasSystemFeature("android.software.picture_in_picture")){Toast.makeText(this,t("هذا الهاتف لا يدعم التصغير داخل صورة.","Picture-in-picture is not supported on this phone."),Toast.LENGTH_LONG).show();return;}if(!prepared){Toast.makeText(this,t("انتظر حتى يبدأ الفيديو ثم جرّب التصغير.","Wait for the video to start, then try picture-in-picture."),Toast.LENGTH_SHORT).show();return;}try{float ratio=Math.max(1f/2.39f,Math.min(2.39f,(float)Math.max(1,video.width)/Math.max(1,video.height)));PictureInPictureParams.Builder params=new PictureInPictureParams.Builder().setAspectRatio(new android.util.Rational(Math.round(ratio*1000),1000));android.graphics.Rect bounds=new android.graphics.Rect();if(video.getGlobalVisibleRect(bounds))params.setSourceRectHint(bounds);hidePlaybackChrome();pipEntering=true;if(!enterPictureInPictureMode(params.build())){pipEntering=false;show();Toast.makeText(this,t("فعّل السماح بصورة داخل صورة من إعدادات التطبيق.","Allow picture-in-picture in the app system settings."),Toast.LENGTH_LONG).show();}}catch(RuntimeException e){pipEntering=false;show();Toast.makeText(this,t("تعذّر بدء وضع الصورة داخل صورة.","Could not start picture-in-picture."),Toast.LENGTH_LONG).show();}}
