 private void settings(){finishScrub(false,true);String[] names={t("تلقائي · احتواء","Auto · Fit"),t("ملء الشاشة","Fill"),t("تمديد","Stretch")},modes={"fit","fill","stretch"};java.util.List<PlayerChoice> options=new ArrayList<>();for(int i=0;i<modes.length;i++){final String mode=modes[i];options.add(new PlayerChoice(names[i],mode.equals(UiSettings.prefs(this).getString("scale","fit")),()->{UiSettings.prefs(this).edit().putString("scale",mode).apply();video.requestLayout();settings();}));}presentChoices(t("أبعاد الصورة","Aspect Ratio"),options);}

