 private void tracks(int type){if(!prepared)return;String title=type==MediaPlayer.TrackInfo.MEDIA_TRACK_TYPE_AUDIO?t("مسار الصوت","Audio Track"):t("الترجمة","Subtitles");if(video.buffered()){presentChoices(title,video.chromeTracks(type,!live&&type==MediaPlayer.TrackInfo.MEDIA_TRACK_TYPE_SUBTITLE?this::pickSubtitle:null,()->tracks(type)));return;}java.util.List<PlayerChoice> options=new ArrayList<>();try{if(engine!=null){int selected=engine.getSelectedTrack(type);if(type==MediaPlayer.TrackInfo.MEDIA_TRACK_TYPE_SUBTITLE)options.add(new PlayerChoice(t("إيقاف","Off"),selected<0,()->{int id=engine.getSelectedTrack(type);if(id>=0)engine.deselectTrack(id);tracks(type);}));MediaPlayer.TrackInfo[] all=engine.getTrackInfo();for(int i=0;i<all.length;i++)if(all[i].getTrackType()==type){final int id=i;String lang=all[i].getLanguage();options.add(new PlayerChoice(lang==null?"Track "+(i+1):lang,selected==i,()->{try{engine.selectTrack(id);}catch(RuntimeException e){Toast.makeText(this,t("المسار غير مدعوم","Track not supported"),1).show();}tracks(type);}));}}}catch(RuntimeException ignored){}presentChoices(title,options);}

 boolean key(String key){java.util.Map<String,Integer> keys=new java.util.HashMap<>();keys.put("RETURN",4);keys.put("LEFT",21);keys.put("RIGHT",22);keys.put("UP",19);keys.put("DOWN",20);keys.put("ENTER",23);keys.put("SETTINGS",82);keys.put("MENU",82);keys.put("INPUT",178);keys.put("GUIDE",172);keys.put("PLAY",126);keys.put("PAUSE",127);keys.put("CHANNELUP",166);keys.put("CHANNELDOWN",167);if(key.equals("HOME")){runOnUiThread(()->{remember();finish();});return true;}Integer code=keys.get(key);if(code==null)return false;runOnUiThread(()->{dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,code));dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,code));});return true;}
 @Override public boolean onKeyDown(int code,KeyEvent e){scheduleHide();if(code==KeyEvent.KEYCODE_BACK&&phoneMode){remember();finish();return true;}if(code==KeyEvent.KEYCODE_BACK&&controls.getVisibility()==View.VISIBLE){finishScrub(false,true);hidePlaybackChrome();return true;}if(code==KeyEvent.KEYCODE_MENU){toggleRightPanel();return true;}if(code==KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE){toggle();return true;}if(code==KeyEvent.KEYCODE_MEDIA_PLAY){phonePlayRequested=true;if(!video.isPlaying())toggle();return true;}if(code==KeyEvent.KEYCODE_MEDIA_PAUSE){phonePlayRequested=false;if(video.isPlaying())toggle();return true;}if(!live&&controls.getVisibility()!=View.VISIBLE&&(code==KeyEvent.KEYCODE_DPAD_LEFT||code==KeyEvent.KEYCODE_DPAD_RIGHT)){beginScrub(code,e.getRepeatCount()>0);return true;}View focused=getCurrentFocus();if(!live&&prepared&&controls.getVisibility()==View.VISIBLE&&(code==KeyEvent.KEYCODE_DPAD_LEFT||code==KeyEvent.KEYCODE_DPAD_RIGHT)&&(focused==null||focused==video)){if(e.getRepeatCount()==0)seek(code==KeyEvent.KEYCODE_DPAD_LEFT?-10000:10000);return true;}if(controls.getVisibility()!=View.VISIBLE&&(code==23||code>=19&&code<=22)){show();return true;}return super.onKeyDown(code,e);}
 boolean pauseForAdhan(){boolean playing=!prepared||video.isPlaying()||scrubPaused&&scrubWasPlaying;finishScrub(false,false);adhanPaused=true;if(prepared&&video.isPlaying())video.pause();return playing;}
 void endAdhan(boolean resume){adhanPaused=false;if(resume&&prepared&&!failed&&!completed&&!isFinishing()&&active==this)video.start();}
 // Phone launcher return may regain the video surface and audio focus after onResume.
 private final Runnable phoneForegroundPlayback=()->{if(phoneMode&&active==this&&hasWindowFocus()&&prepared&&resumeOnReturn&&phonePlayRequested&&!adhanPaused&&!completed&&!failed&&!video.isPlaying()){video.start();update();}};
 private void retryPhoneForegroundPlayback(){if(!phoneMode)return;timer.removeCallbacks(phoneForegroundPlayback);timer.postDelayed(phoneForegroundPlayback,180);timer.postDelayed(phoneForegroundPlayback,500);timer.postDelayed(phoneForegroundPlayback,1100);}
 @Override protected void onResume(){super.onResume();ParentalTimer.enter(this,mediaId());active=this;retryPhoneForegroundPlayback();if(phoneMode&&prepared&&!phonePlayRequested){video.pause();}else if(prepared&&!adhanPaused&&resumeOnReturn){video.start();if(stableRecovery!=null)timer.postDelayed(stableRecovery,30000);}else if(retryPending&&!failed){retryPending=false;beginSource(false);}else if(!prepared&&!failed){timer.removeCallbacks(sourceTimeout);timer.postDelayed(sourceTimeout,live?20000:45000);}timer.postDelayed(checkpoint,1000);}
 @Override public void onBackPressed(){backFromPlayback();}
 @Override public boolean onKeyUp(int code,KeyEvent e){if(code==KeyEvent.KEYCODE_BACK&&phoneMode)return true;if(code==KeyEvent.KEYCODE_DPAD_LEFT||code==KeyEvent.KEYCODE_DPAD_RIGHT)finishScrub(true,true);return super.onKeyUp(code,e);}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(!focused)finishScrub(false,true);else if(phoneMode&&active==this&&prepared&&resumeOnReturn&&phonePlayRequested&&!adhanPaused&&!completed&&!failed&&!video.isPlaying()){video.start();update();}if(focused)retryPhoneForegroundPlayback();}
 void leaveForInput(){suspendPlayback();prepared=false;resumeOnReturn=false;video.stopPlayback();finish();}
 private void suspendPlayback(){timer.removeCallbacks(phoneForegroundPlayback);diagnostics.end(SystemClock.uptimeMillis());bufferingNotice.setVisibility(View.GONE);if(reconnect!=null)timer.removeCallbacks(reconnect);if(stableRecovery!=null)timer.removeCallbacks(stableRecovery);timer.removeCallbacks(sourceTimeout);resumeOnReturn=prepared&&!completed&&!failed&&((phoneMode?phonePlayRequested:video.isPlaying())||resumeAfterSeek);finishScrub(false,false);resumeAfterSeek=false;ParentalTimer.leave(mediaId());remember();timer.removeCallbacks(checkpoint);timer.removeCallbacks(hide);if(active==this)active=null;video.pause();}
 @Override protected void onPause(){if(!pipEntering&&!isInPictureInPictureMode())suspendPlayback();super.onPause();}
 @Override protected void onStop(){if(active==this)suspendPlayback();super.onStop();}
 @Override protected void onDestroy(){sourceGeneration++;itemEpoch++;metadataWorker.shutdownNow();timer.removeCallbacksAndMessages(null);if(channelBrowser!=null)channelBrowser.close();video.stopPlayback();super.onDestroy();}
